refentry.refsect1:
  &reftitle.returnvalues;

string को प्रारम्भिक खण्डको लम्बाइ return गर्दछ, जसमा पूर्ण रूपमा characters का characters समावेश हुन्छन्।


जब offset parameter set गरिन्छ, तब return गरिएको length string को beginning from नभई यो position from सुरु गरेर गणना गरिन्छ।

  &reftitle.examples;



    strspn को उदाहरण


<?php
// subject does not start with any characters from mask
var_dump(strspn("foo", "o"));

// examine two characters from subject starting at offset 1
var_dump(strspn("foo", "o", 1, 2));

// examine one character from subject starting at offset 1
var_dump(strspn("foo", "o", 1, 1));
?>


    &example.outputs;


int(0)
int(2)
int(1)
